:host {
  display: block;
  font-family: Roboto, 'Helvetica Neue', sans-serif;
}

.seat-page {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  padding: 16px 24px 32px;
  text-align: center;

  h1 {
    margin: 0;
    font-size: 28px;
  }
}

.subtitle,
.limit {
  margin: 0;
}

.limit {
  color: #616161;
}

.auditorium {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 12px;
  margin-top: 8px;
}

.screen {
  width: 560px;
  padding: 6px 0;
  background: #e0e0e0;
  border-radius: 0 0 50% 50%;
  font-size: 13px;
  letter-spacing: 4px;
}

.seat-map {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.seat-row {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 4px;
}

.row-label {
  width: 24px;
  font-size: 12px;
  color: #616161;
}

.block {
  display: flex;
  gap: 4px;
  flex: none;
}

.entrance {
  width: 140px;
  flex: none;
}

.aisle {
  width: 68px;
  flex: none;
}

.seat,
.couch {
  height: 32px;
  width: 32px;
  flex: none;
  padding: 0;
  border: 0;
  border-radius: 4px;
  color: #fff;
  font: 12px Roboto, 'Helvetica Neue', sans-serif;
  cursor: pointer;
}

.couch {
  width: 68px;
}

