import { TestBed } from '@angular/core/testing';
import { provideRouter } from '@angular/router';
import { AUDITORIUM } from './auditorium';
import { SeatMap } from './seat-map/seat-map';

const view = {
  screening: { id: 1, movieId: 1, date: '2026-09-15', time: '16:00', occupiedSeats: ['R3C7', 'R15C5'] },
  movie: { id: 1, title: 'The Silent Harbor', genre: 'Drama', runtimeMinutes: 128, format: 'PL subtitles' as const },
};

describe('verify', () => {
  beforeEach(() => {
    sessionStorage.clear();
    TestBed.configureTestingModule({ providers: [provideRouter([])] });
  });

  it('auditorium counts', () => {
    const cells = AUDITORIUM.flatMap((r) => r.blocks.flat());
    expect(cells.filter((c) => c.kind === 'seat').length).toBe(296);
    expect(cells.filter((c) => c.kind === 'couch').length).toBe(12);
    expect(cells.filter((c) => c.accessible).length).toBe(6);
  });

  it('renders and selects', () => {
    const fixture = TestBed.createComponent(SeatMap);
    fixture.componentRef.setInput('view', view);
    fixture.detectChanges();
