describe('verify checkout', () => {
  beforeEach(() => {
    sessionStorage.clear();
    sessionStorage.setItem(
      'cinescope.booking',
      JSON.stringify({
        screeningId: 1,
        selections: [{ row: 15, column: 1, couch: true }, { row: 7, column: 12, couch: false }],
        form: { firstName: '', lastName: '', email: '', confirmEmail: '', phone: '', terms: false },
        paid: false,
      }),
    );
    TestBed.configureTestingModule({
      providers: [provideRouter([]), provideHttpClient(), provideHttpClientTesting(), provideNativeDateAdapter()],
    });
  });

  it('validates and pays', async () => {
    const http = TestBed.inject(HttpTestingController);
    const fixture = TestBed.createComponent(Checkout);
    fixture.detectChanges();
    const el = fixture.nativeElement as HTMLElement;
    expect((el.querySelector('[data-testid=pay-button]') as HTMLElement).textContent?.trim()).toBe('Pay 114.00 PLN');
    expect(el.querySelector('[data-testid=first-name-label]')?.textContent).toBe('First name *');
    expect(el.querySelector('[data-testid=phone-label]')?.textContent).toBe('Phone number');

    (el.querySelector('[data-testid=pay-button]') as HTMLElement).click();
    fixture.detectChanges();
    expect(el.querySelector('[data-testid=first-name-error]')?.textContent).toBe('First name is required');
    expect(el.querySelector('[data-testid=terms-error]')?.textContent).toBe('You must accept the terms and conditions');
    expect(document.body.querySelector('[data-testid=toast]')?.textContent).toBe('The form contains errors');
    http.expectNone(`${API}/reservations`);

    const set = (testid: string, value: string) => {
      const input = el.querySelector(`[data-testid=${testid}]`) as HTMLInputElement;
      input.value = value;
      input.dispatchEvent(new Event('input'));
      fixture.detectChanges();
    };
    set('first-name-input', 'A');
    expect(el.querySelector('[data-testid=first-name-error]')?.textContent).toBe('First name must be at least 2 characters');
    set('first-name-input', 'Anna');
    set('last-name-input', 'Kowalska');
    set('email-input', 'a@b');
    expect(el.querySelector('[data-testid=email-error]')?.textContent).toBe('Enter a valid email address');
    set('email-input', 'anna.kowalska@example.com');
    set('confirm-email-input', 'anna@example.com');
    expect(el.querySelector('[data-testid=confirm-email-error]')?.textContent).toBe('Email addresses do not match');
    set('confirm-email-input', 'anna.kowalska@example.com');
    expect(el.querySelector('[data-testid=confirm-email-error]')).toBeNull();
    set('phone-input', '12345');
    expect(el.querySelector('[data-testid=phone-error]')?.textContent).toBe('Phone number must be exactly 9 digits');
    set('phone-input', '');
    expect(el.querySelector('[data-testid=phone-error]')).toBeNull();
    (fixture.componentInstance as unknown as { setTerms(v: boolean): void }).setTerms(true);
    fixture.detectChanges();
    expect(el.querySelector('[data-testid=terms-error]')).toBeNull();
    expect(JSON.parse(sessionStorage.getItem('cinescope.booking')!).form.firstName).toBe('Anna');

    (el.querySelector('[data-testid=pay-button]') as HTMLElement).click();
    fixture.detectChanges();
    const req = http.expectOne(`${API}/reservations`);
    expect(req.request.body).toEqual({
      screeningId: 1,
      seats: ['R15C1', 'R15C2', 'R7C12'],
      customer: { firstName: 'Anna', lastName: 'Kowalska', email: 'anna.kowalska@example.com', phone: '' },
      totalPrice: 114,
    });
    fixture.detectChanges();
    expect((el.querySelector('[data-testid=pay-button]') as HTMLButtonElement).disabled).toBe(true);
    expect(el.querySelector('[data-testid=pay-button]')?.textContent?.trim()).toBe('Processing…');
    req.flush({ id: 1 }, { status: 201, statusText: 'Created' });
    await fixture.whenStable();
    expect(JSON.parse(sessionStorage.getItem('cinescope.booking')!).paid).toBe(true);
  });
});

