import { provideHttpClient } from '@angular/common/http';
import { HttpTestingController, provideHttpClientTesting } from '@angular/common/http/testing';
import { TestBed } from '@angular/core/testing';
import { provideNativeDateAdapter } from '@angular/material/core';
import { provideRouter } from '@angular/router';
import { Checkout } from './checkout/checkout';
import { MovieList } from './movie-list/movie-list';

const API = 'http://localhost:3000';
const movies = [
  { id: 1, title: 'The Silent Harbor', genre: 'Drama', runtimeMinutes: 128, format: 'PL subtitles' },
  { id: 2, title: 'Neon Circuit', genre: 'Sci-Fi', runtimeMinutes: 142, format: 'PL subtitles' },
];

describe('verify movie list', () => {
  beforeEach(() => {
    sessionStorage.clear();
    TestBed.configureTestingModule({
      providers: [provideRouter([]), provideHttpClient(), provideHttpClientTesting(), provideNativeDateAdapter()],
    });
  });

  it('loads, shows cards, empty and error states', async () => {
    const http = TestBed.inject(HttpTestingController);
    const fixture = TestBed.createComponent(MovieList);
    fixture.detectChanges();
    const el = fixture.nativeElement as HTMLElement;
    expect(el.querySelector('[data-testid=movies-loading]')).not.toBeNull();
    expect(el.querySelectorAll('[data-testid=day-button]').length).toBe(5);
    expect(el.querySelector('[data-testid=day-button][data-selected=true]')?.textContent).toBe('Today');

    const today = (el.querySelector('[data-testid=day-button]') as HTMLElement).dataset['date'];
    const movieReq = http.expectOne(`${API}/movies`);
    const screeningReq = http.expectOne((r) => r.url === `${API}/screenings` && r.params.get('date') === today);
    movieReq.flush(movies);
    screeningReq.flush([
      { id: 9, movieId: 2, date: today, time: '19:30', occupiedSeats: [] },
      { id: 5, movieId: 2, date: today, time: '15:00', occupiedSeats: [] },
      { id: 1, movieId: 1, date: today, time: '16:00', occupiedSeats: [] },
    ]);
    await fixture.whenStable();
    fixture.detectChanges();
    const cards = el.querySelectorAll('[data-testid=movie-card]');
    expect(cards.length).toBe(2);
    expect(cards[0].querySelector('[data-testid=movie-title]')?.textContent).toBe('The Silent Harbor');
    expect(cards[0].querySelector('[data-testid=movie-runtime]')?.textContent).toBe('128 min');
    expect(cards[1].querySelector('[data-testid=movie-format]')?.textContent).toBe('PL subtitles');
    const times = Array.from(cards[1].querySelectorAll('[data-testid=screening-button]')).map((b) => b.textContent);
    expect(times).toEqual(['15:00', '19:30']);
    expect(cards[1].querySelector('[data-testid=screening-button]')?.getAttribute('data-screening-id')).toBe('5');

    const labels = Array.from(el.querySelectorAll('[data-testid=day-button]')).map((b) => b.textContent);
    expect(labels[0]).toBe('Today');
    expect(labels.length).toBe(5);
    http.verify();
  });

  it('shows error and retries', async () => {
    const http = TestBed.inject(HttpTestingController);
    const fixture = TestBed.createComponent(MovieList);
    fixture.detectChanges();
    http.match((r) => r.url.startsWith(API)).forEach((req) => req.flush('x', { status: 500, statusText: 'err' }));
    await fixture.whenStable();
    fixture.detectChanges();
    const el = fixture.nativeElement as HTMLElement;
    expect(el.querySelector('[data-testid=movies-error]')?.textContent).toBe('Failed to load movies');
    (el.querySelector('[data-testid=movies-retry-button]') as HTMLElement).click();
    fixture.detectChanges();
    expect(el.querySelector('[data-testid=movies-loading]')).not.toBeNull();
    http.match((r) => r.url.startsWith(API)).forEach((req) => req.flush([]));
    await fixture.whenStable();
    fixture.detectChanges();
    expect(el.querySelector('[data-testid=movies-empty]')?.textContent).toBe('No screenings on this day');
  });
});

describe('verify checkout', () => {
