    (el.querySelector('[data-testid=pay-button]') as HTMLElement).click();
    fixture.detectChanges();
    const req = http.expectOne(`${API}/reservations`);
    expect(req.request.body).toEqual({
      screeningId: 1,
      seats: ['R15C1', 'R15C2', 'R7C12'],
      customer: { firstName: 'Anna', lastName: 'Kowalska', email: 'anna.kowalska@example.com', phone: '' },
      totalPrice: 121,
    });
    fixture.detectChanges();
    expect((el.querySelector('[data-testid=pay-button]') as HTMLButtonElement).disabled).toBe(true);
    expect(el.querySelector('[data-testid=pay-button]')?.textContent?.trim()).toBe('Processing…');
    req.flush({ id: 1 }, { status: 201, statusText: 'Created' });
    await fixture.whenStable();
    expect(JSON.parse(sessionStorage.getItem('cinescope.booking')!).paid).toBe(true);
  });
});

